function addBorderUneven(w, h, tL, tR, tT, tB){ return { w:w+tL+tR, h:h+tT+tB, tL:tL, tR:tR, tT:tT, tB:tB }; }
var EXPORTS={ addBorder:addBorder, addBorderUneven:addBorderUneven };

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.BorderForgePure = EXPORTS; }
